-- 20260731000002_seed_exercise.sql
-- Generated from shared/src/commonMain/composeResources/files/exercises.json (ADR-007's merged shape).
-- One-time seed of the static Exercise Library catalog into Postgres (read-only mirror, see ADR-008).

on conflict (id) do update set
  name = excluded.name, equipment_category = excluded.equipment_category, movement_pattern = excluded.movement_pattern,
  level = excluded.level, primary_muscle_group = excluded.primary_muscle_group,
  target_muscles_primary = excluded.target_muscles_primary, target_muscles_secondary = excluded.target_muscles_secondary,
  flag_exclusion = excluded.flag_exclusion, flag_priority = excluded.flag_priority,
  instructions_id = excluded.instructions_id, common_mistakes_id = excluded.common_mistakes_id, safety_tips_id = excluded.safety_tips_id;
